    target = attack['target']
    text = attack['text']

    # 处理 unknown kind
    if kind == 'unknown':
        # 根据内容推断 kind
        if '预测' in text or '偏差' in text or '范围' in text:
            kind = 'constraint'
        elif '替代' in text or '机制' in text or '声称' in text:
            kind = 'new_h'
        elif '奥卡姆' in text or '参数' in text or '简约' in text:
            kind = 'no_change'
        else:
            kind = 'constraint'  # 默认

    # 处理 target
    if target == 'unknown':
        # 根据内容推断 target
        if 'H1' in text and 'H3' in text:
            target = 'H1 vs H3'
        elif 'H1' in text:
            target = 'H1'
        elif 'H3' in text:
            target = 'H3'
        else:
            target = 'H3'  # 默认（大部分 H3 攻击来自第二个子代理）

    # 修正 "H1 vs H3" 为标准格式
    if target == 'H1 vs H3':
        target = 'H1'  # 主要攻击 H1

    return {
        'kind': kind,
        'target': target,
        'text': text
    }

normalized = [normalize_attack(a) for a in attacks]

